function combine(op){let list=chosen();if(list.some(hasAnimation))return toast("Group pieces before animating them. Remove animation before regrouping.");if(list.length<2)return toast('Select at least two pieces first.');if(list.some(o=>o.locked))return toast('Unlock the selected pieces first.');let b=bounds(list);checkpoint();cinemaDetachReferences(list.map(o=>o.id));list.forEach(o=>cinemaDetach(o));let children=copy(list).map(o=>{o.x-=b.cx;o.y-=b.cy;return o});let o={id:id(),type:op?'boolean':'group',name:op?({union:'United felt',subtract:'Cut felt',intersect:'Intersection',xor:'Difference'}[op]):'Group',op,children,x:b.cx,y:b.cy,w:b.w,h:b.h,bw:b.w,bh:b.h,rotation:0,color:currentColor,stitch,fiber};let top=Math.max(...list.map(o=>items().findIndex(x=>x.id===o.id)));let remain=items().filter(x=>!selected.includes(x.id));let insertion=items().slice(0,top+1).filter(x=>!selected.includes(x.id)).length;remain.splice(insertion,0,o);scene().items=remain;selected=[o.id];refresh();if(op)toast('Combined into one felt shape. Ungroup restores the original pieces.')}
function ungroup(){let groups=chosen().filter(o=>o.children&&!o.locked);if(!groups.length)return toast('Select a group or Boolean shape first.');if(groups.some(hasAnimation))return toast('Remove animation before ungrouping; the current pose will be kept.');checkpoint();cinemaDetachReferences(groups.map(o=>o.id));let result=[];for(const g of groups){let r=g.rotation*Math.PI/180,sx=g.w/g.bw*(g.flipX?-1:1),sy=g.h/g.bh*(g.flipY?-1:1);let kids=copy(g.children).map(o=>{let x=o.x*sx,y=o.y*sy;o.x=g.x+x*Math.cos(r)-y*Math.sin(r);o.y=g.y+x*Math.sin(r)+y*Math.cos(r);o.w*=Math.abs(sx);o.h*=Math.abs(sy);o.rotation=g.rotation+o.rotation*(sx*sy<0?-1:1);if(g.opacity!==undefined||o.opacity!==undefined)o.opacity=(o.opacity??1)*(g.opacity??1);if(sx<0)o.flipX=!o.flipX;if(sy<0)o.flipY=!o.flipY;return o});let n=items().findIndex(x=>x.id===g.id);items().splice(n,1,...kids);result.push(...kids.map(o=>o.id))}selected=result;refresh()}
