function refreshSelection(){let list=chosen(),one=list.length===1?list[0]:null;$('selectionTitle').textContent=one?one.name:list.length?`${list.length} pieces selected`:'Make it your own';$('pieceWidth').value=one?Math.round(one.w):'';$('rotation').value=one?Math.round(one.rotation||0):'';$('pieceWidth').disabled=!one||one.locked;$('rotation').disabled=!one||one.locked;$('lock').textContent=one?.locked?'Unlock':'Lock';$('delete').disabled=!list.some(o=>!o.locked);$('duplicate').disabled=!list.some(o=>!o.locked);$('group').disabled=list.length<2;$('ungroup').disabled=!list.some(o=>o.children&&!o.locked);if(one&&one.type!=='group'){if(one.color){$('color').value=one.color;$('hex').value=one.color}$('stitch').checked=!!one.stitch;$('fiber').value=(one.fiber??fiber)*100}syncBubbleEditor();renderLayers();renderAnimationUI();updateSelectionChrome();if(studioUIReady){updateStudioHints();FeltCinema?.sync();window.FeltStoryTools?.sync()}draw()}
