function addAsset(a){if(a.storyPack)return storyAddProp(a.storyPack);if(a.puppet)return addCinemaPuppet(a);if(a.foreground){const im=imageMap.get(a.id);if(im)return add({id:id(),type:'asset',asset:a.id,name:a.name,x:W/2,y:H/2,w:W,h:H,bw:im.width,bh:im.height,rotation:0,color:null,fiber:0,stitch:false,depth:'foreground'});return}const im=imageMap.get(a.id);if(!im)return;if(a.music){const bg=ART.backgrounds[scene().bg],gap=bg?.staff==='grand'?50:80,ratio=gap/150,m=a.music,originY=8+m.bounds[3]*.6;let anchor=bg?.staff==='grand'?300:450;if(m.anchor==='whole-rest')anchor-=gap;if(m.anchor==='treble')anchor+=gap;if(m.anchor==='bass')anchor-=gap;add({id:id(),type:'asset',asset:a.id,name:a.name,x:W/2,y:anchor+(im.height/2-originY)*ratio,w:im.width*ratio,h:im.height*ratio,bw:im.width,bh:im.height,rotation:0,color:null,fiber:0,stitch:false});return}let w=a.defaultWidth||210,h=w*im.height/im.width;if(a.maxInitialHeight&&h>a.maxInitialHeight){w*=a.maxInitialHeight/h;h=a.maxInitialHeight}add({id:id(),type:'asset',asset:a.id,name:a.name,x:cameraAt(scene(),animTime).x+(Math.random()-.5)*80/cameraAt(scene(),animTime).zoom,y:cameraAt(scene(),animTime).y,w,h,bw:im.width,bh:im.height,rotation:0,color:null,fiber:0,stitch:false})}
