function validateProject(p){if(p.format!=='felt-and-fable'||p.version!==1||!Array.isArray(p.scenes)||!p.scenes.length||p.scenes.length>100)throw Error('Choose a Felt & Fable story JSON file.');delete p.phraseVideo;delete p.classroomHolds;let count=0;function check(o,depth=0){if(++count>15000||depth>20||!['shape','path','pen','text','asset','group','boolean','bubble','puppet'].includes(o.type))throw Error('Invalid piece data.');for(let k of ['x','y','w','h','bw','bh'])if(!Number.isFinite(o[k])||(k!=='x'&&k!=='y'&&o[k]<=0)||Math.abs(o[k])>12000)throw Error('Invalid piece dimensions.');if(!Number.isFinite(o.rotation))throw Error('Invalid rotation.');validateAnimation(o);validateBubble(o);if(o.children){if(!Array.isArray(o.children))throw Error('Invalid group.');o.children.forEach(c=>check(c,depth+1))}if(o.points&&(!Array.isArray(o.points)||o.points.length>100000||o.points.some(a=>!Array.isArray(a)||a.length!==2||a.some(v=>!Number.isFinite(v)))))throw Error('Invalid drawing.')}p.scenes.forEach(s=>{validateCamera(s);if(!Array.isArray(s.items))throw Error('Invalid scene.');s.items.forEach(o=>check(o))});if(!Array.isArray(p.custom))p.custom=[];p.custom.forEach(o=>check(o));for(const v of Object.values(p.imports||{}))if(typeof v!=='string'||!/^data:image\/(png|jpeg|webp|gif);base64,/.test(v))throw Error('Invalid imported image.');p.active=Math.max(0,Math.min(p.scenes.length-1,Number(p.active)||0));validateAudioProject(p);validateCinemaProject(p);validateDirectorProject(p);validateTalkProject(p);validatePerformanceProject(p);validateMovieFX(p);validateStoryTools(p);validateStudio(p);reuseValidate(p);productionValidate(p);craftValidate(p);phraseValidate(p);deskValidate(p);rigValidate(p);cineValidate(p);return p}
