function timelinePointerMove(e){
 const gesture=timelineGesture;if(!gesture||gesture.pointerId!==e.pointerId)return;e.preventDefault();
 if(gesture.kind==='pan'){$('timelineViewport').scrollLeft=gesture.scroll-(e.clientX-gesture.startX);return}
 if(Math.abs(e.clientX-gesture.startX)>3)gesture.moved=true;
 if(gesture.kind==='key'){
 if(!gesture.moved)return;
 const max=Math.min(7199,sceneSeconds(scene())-1/ANIMATION_FPS),t=Math.min(max,timelineTimeAt(e.clientX));
 if(gesture.piece.keyframes.some(k=>k!==gesture.key&&Math.abs(k.t-t)<KEY_TOLERANCE))return;
 if(Math.abs(t-gesture.key.t)>1e-8){if(!gesture.checkpoint){checkpoint();scene().duration=Math.max(scene().duration||6,gesture.total);gesture.checkpoint=true}gesture.key.t=t;gesture.piece.keyframes.sort((a,b)=>a.t-b.t);gesture.button.style.left=(t/sceneSeconds(scene())*100)+'%';dirty=true;updateSaveState()}
 queueTimelineSeek(t);
 }else queueTimelineSeek(timelineTimeAt(e.clientX));
}
function timelinePointerEnd(e){
 const gesture=timelineGesture;if(!gesture||gesture.pointerId!==e.pointerId)return;
 flushTimelineSeek();timelineGesture=null;const surface=$('timelineSurface');surface.classList.remove('scrubbing','panning');if(surface.hasPointerCapture?.(e.pointerId))surface.releasePointerCapture(e.pointerId);
 refreshSelection();if(gesture.checkpoint){renderScenes();updateUndo()}
}
$('animDuration').onchange=e=>setSceneLength(e.target.value);
$('sceneShorter').onclick=()=>setSceneLength(Math.max(1,sceneSeconds(scene())-1));
$('sceneLonger').onclick=()=>setSceneLength(Math.min(7199,sceneSeconds(scene())+1));
$('sceneDuration').onchange=e=>setSceneLength(e.target.value);
$('timelineZoom').onchange=e=>setTimelineZoom(e.target.value);
$('timelineFit').onclick=()=>setTimelineZoom(1);
$('timelinePanLeft').onclick=()=>{$('timelineViewport').scrollLeft-=Math.max(50,$('timelineViewport').clientWidth*.7)};
$('timelinePanRight').onclick=()=>{$('timelineViewport').scrollLeft+=Math.max(50,$('timelineViewport').clientWidth*.7)};
$('timelineSurface').onpointerdown=timelinePointerDown;$('timelineSurface').onpointermove=timelinePointerMove;
$('timelineSurface').onpointerup=timelinePointerEnd;$('timelineSurface').onpointercancel=timelinePointerEnd;$('timelineSurface').onlostpointercapture=timelinePointerEnd;
$('timelineSurface').onkeydown=e=>{let t;if(e.key==='ArrowLeft')t=animTime-(e.shiftKey?1:1/ANIMATION_FPS);else if(e.key==='ArrowRight')t=animTime+(e.shiftKey?1:1/ANIMATION_FPS);else if(e.key==='Home')t=0;else if(e.key==='End')t=sceneSeconds(scene());else return;e.preventDefault();e.stopPropagation();seekAnimation(t)};
window.addEventListener('resize',()=>{timelineLayoutKey='';updateTimelineLayout()});
new ResizeObserver(()=>{timelineLayoutKey='';updateTimelineLayout()}).observe($('timelineViewport'));
function syncInspectorSections(){
 const count=chosen().length;$('selectionActions').hidden=count===0;$('transformSection').hidden=count===0;$('arrangeSection').hidden=count===0;$('combineSection').hidden=count<2;
 $('lock').disabled=count===0;
}
