function syncPanelLabels(){const cl=document.body.classList,small=window.innerWidth<=900,focus=cl.contains('focus-board');$('toggleCollection').textContent=(!focus&&(small?cl.contains('mobile-collection'):!cl.contains('hide-collection'))?'Hide':'Show')+' Collection';$('toggleInspector').textContent=(!focus&&(small?cl.contains('mobile-properties'):!cl.contains('hide-inspector'))?'Hide':'Show')+' Properties'}
